  flexGauges() { const cross = PEOPLE.filter(p => p.cert.includes('电力电缆作业证') || p.cert.includes('继电保护作业资格')).length + LAB.people.filter(p => p.cert.includes('电力电缆作业证')).length + 1; const tr = DB.transfers(); return '<div class="gauge3"><div><b>' + cross + '</b><span>可跨班组作业人数</span><em>持电缆 / 继保等跨专业资质</em></div><div><b>' + tr.filter(t => t.st === '已确认').length + '/' + tr.length + '</b><span>调配已确认 / 发起</span><em>柔性团队在办</em></div><div><b>' + (LAB.borrowed.length + tr.filter(t => t.st === '已确认').length) + '</b><span>在借人员</span><em>' + LAB.borrowed.map(b => b.n + '→' + b.to).join('、') + '</em></div></div>'; },
  /* ---------- 跨班组调配模拟 → 发起（待两位班长确认） ---------- */
