  transferBlock() { const tr = DB.transfers().filter(t => t.st === '待确认' && (t.to === TEAM.name || t.from === TEAM.name)); if (!tr.length) return ''; return '<div class="card" id="trblock"><div class="h"><b>跨班组调配 · 待你确认</b><span>' + tr.length + ' 条 · 由' + TEAM.dept + '发起，人选和期间你可以改</span></div><div class="jobs">' + tr.map(t => '<div class="job"><span style="font-size:11.5px;color:var(--ink);white-space:normal">' + h(t.who) + '：' + h(t.from) + ' → ' + h(t.to) + '，' + h(t.start) + ' 起 ' + t.days + ' 天<br><span class="note">' + h(t.why) + '</span></span><span class="ops"><button data-act="tr-ok" data-id="' + t.id + '">确认</button><button class="g" data-act="tr-back" data-id="' + t.id + '">退回</button></span></div>').join('') + '</div></div>'; },
