      finish: () => { const H = DB.hours().filter(r => r.added); XW.spot({ title: '完工记工时', cols: ['日期', '人员', '作业', '小时'], rows: H.map(r => [r.d, r.who, r.job, r.h]), me: H.map((r, i) => i), sumCol: 3, unit: 'h', text: H.length ? '今天完工记了 ' + H.length + ' 条工时。' : '今天还没有完工记录。' }); },
