  'sup-urge'(el) { const sent = LS.get('sup_sent', {}); sent[el.dataset.id] = DB.now(); LS.set('sup_sent', sent); DB.notify('赵立群', '督办：华发民公用柜 电容故障已超期，请今日闭环并回传（' + TEAM.dept + '）', '已读', true); DB.log('督办', '华发民公用柜 电容故障 → 赵立群'); XW.fly('督办已发 · 赵立群'); const host = $('#riskbody'); if (host) { host.innerHTML = PAGES.risk.body(); CH.mount(host); } XW.answer('督办发给赵立群了，他那边今日工作台的催办卡会亮；闭环后这条自动消掉。', null, { confirm: false }); },
  'sup-notify'(el) { const sent = LS.get('sup_sent', {}); sent[el.dataset.id] = DB.now(); LS.set('sup_sent', sent); DB.notify(el.dataset.who, el.dataset.arg + '（' + TEAM.dept + '）', '已读', true); DB.log('提醒', el.dataset.arg + ' → ' + el.dataset.who); XW.fly('提醒已发 · ' + el.dataset.who); const host = $('#riskbody'); if (host) { host.innerHTML = PAGES.risk.body(); CH.mount(host); } XW.answer('发给' + el.dataset.who + '了：' + el.dataset.arg + '。', null, { confirm: false }); },
  'sim-from'(el) { const from = el.value; const who = $('#sm-who'); if (who) who.innerHTML = SUPER.peopleOf(from).map(n => '<option>' + h(n) + '</option>').join(''); },
  'sim-run'() { SUPER.simState = SUPER.readSim(); const host = $('#riskbody'); if (host) { host.innerHTML = SUPER.simHTML(); CH.mount(host); } ACT['sim-say'](); },
  'sim-say'() { const f = SUPER.simState; if (!f) return; const imp = SUPER.simImpact(f); XW.answer(f.who + '从' + f.from + '借到' + f.to + ' ' + f.days + ' 天：' + (imp.ok ? '证书够、工时在约定内、借出班组下限仍满足，可以发起，等两位班长确认。' : imp.warns.join('；') + '。' + (imp.alt ? '同班里' + imp.alt.n + '有电缆证、本周 ' + imp.alt.wk + ' 小时，改借他更稳。' : '')), null, { confirm: false }); },
